using System.IO;
using System.Windows;
using System.Windows.Controls;
using MySqlConnector;
namespace WoWItemEditor;
internal sealed class SettingsWindow : Window
{
    private readonly Dictionary<string,TextBox> fields=[];
    private readonly PasswordBox password=new(){Background=TooltipView.Brush("#202125"),Foreground=System.Windows.Media.Brushes.White,BorderBrush=System.Windows.Media.Brushes.DimGray,Padding=new Thickness(8)};
    private readonly ComboBox ssl=new(){ItemsSource=Enum.GetNames<MySqlSslMode>()};
    private readonly CheckBox downloads=new(){Content="Download missing model assets from the client CDN",Foreground=System.Windows.Media.Brushes.LightGray};
    private readonly TextBlock feedback=DesignerWindow.Text("",12);
    private readonly EditorSettings original;
    internal EditorSettings? Result {get;private set;}
    internal SettingsWindow(bool firstRun=false)
    {
        original=AppSettings.Current;Title=firstRun?"Welcome to WoWItemEditor · Setup":"WoWItemEditor · Settings";Width=800;Height=850;MinWidth=650;MinHeight=600;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=TooltipView.Brush("#232428");
        var root=new DockPanel{Margin=new Thickness(20)};Content=root;var title=DesignerWindow.Text(firstRun?"Set up your server connection":"Settings",23);DockPanel.SetDock(title,Dock.Top);root.Children.Add(title);
        var bottom=new StackPanel{Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);feedback.TextWrapping=TextWrapping.Wrap;bottom.Children.Add(feedback);var actions=new WrapPanel();bottom.Children.Add(actions);var test=DesignerWindow.Button("Test connection",actions);test.Click+=async(_,_)=>{test.IsEnabled=false;try{var draft=Read();draft.Validate(false);feedback.Text="Connecting and checking database access…";await Task.Run(async()=>{foreach(string schema in new[]{draft.HotfixDatabase,draft.WorldDatabase,draft.CharacterDatabase}){await using var db=new MySqlConnection(AppSettings.Connection(draft,schema).ConnectionString);await db.OpenAsync();await using var cmd=new MySqlCommand("SELECT 1",db);await cmd.ExecuteScalarAsync();}});feedback.Text="Connection succeeded for hotfix, world and character databases. No data was changed.";}catch(Exception ex){feedback.Text="Connection failed: "+SafeError(ex);}finally{test.IsEnabled=true;}};
        var prepare=DesignerWindow.Button("Prepare backup / history…",actions);prepare.Click+=async(_,_)=>{prepare.IsEnabled=false;try{var candidate=Read();candidate.Validate(false);feedback.Text="Creating missing backup database and history tables…";await EditorStorage.Prepare(candidate);feedback.Text="Backup database and history tables are ready. Existing history was preserved. These credentials were not saved.";}catch(Exception ex){feedback.Text=SafeError(ex);}finally{prepare.IsEnabled=true;}};
        DesignerWindow.Button(firstRun?"Save & start":"Save settings",actions).Click+=(_,_)=>{try{var draft=Read();AppSettings.Save(draft);Result=draft;DialogResult=true;}catch(Exception ex){feedback.Text=SafeError(ex);}};DesignerWindow.Button("Cancel",actions).Click+=(_,_)=>Close();
        var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};root.Children.Add(scroll);var form=new StackPanel();scroll.Content=form;
        void Section(string label){var heading=DesignerWindow.Text(label,16);heading.Margin=new Thickness(0,16,0,8);form.Children.Add(heading);}
        TextBox Field(string key,string label,string value,bool folder=false){form.Children.Add(DesignerWindow.Text(label,12));var row=new DockPanel{Margin=new Thickness(0,3,0,9)};form.Children.Add(row);if(folder){var browse=new Button{Content="Browse…",Margin=new Thickness(8,0,0,0)};DockPanel.SetDock(browse,Dock.Right);row.Children.Add(browse);browse.Click+=(_,_)=>{var picker=new Microsoft.Win32.OpenFolderDialog{Title=label};if(Directory.Exists(fields[key].Text))picker.InitialDirectory=fields[key].Text;if(picker.ShowDialog(this)==true)fields[key].Text=picker.FolderName;};}var edit=new TextBox{Text=value};fields[key]=edit;row.Children.Add(edit);return edit;}
        Section("MariaDB connection");Field("Server","Host / IP address",original.Server);Field("Port","Port",original.Port.ToString());Field("User","User",original.User);form.Children.Add(DesignerWindow.Text("Password (encrypted for your Windows account)",12));password.Password=original.Password;password.Margin=new Thickness(0,3,0,9);form.Children.Add(password);form.Children.Add(DesignerWindow.Text("TLS mode",12));ssl.SelectedItem=original.SslMode;form.Children.Add(ssl);Field("Timeout","Connection timeout (seconds)",original.ConnectionTimeout.ToString());
        Section("Database names");Field("Hotfix","Hotfix database",original.HotfixDatabase);Field("World","World database",original.WorldDatabase);Field("Characters","Character database",original.CharacterDatabase);Field("Backup","Editor history / backup database",original.BackupDatabase);
        Section("Folders");var dataButton=DesignerWindow.Button("Choose server data root (fills DB2 and maps)…",form);dataButton.Click+=(_,_)=>{var picker=new Microsoft.Win32.OpenFolderDialog{Title="Choose server data root containing dbc and maps"};if(picker.ShowDialog(this)!=true)return;fields["Db2"].Text=Path.Combine(picker.FolderName,"dbc","enUS");fields["Maps"].Text=Path.Combine(picker.FolderName,"maps");};Field("Db2","Extracted DB2 folder · required (contains ItemSparse.db2)",original.Db2Folder,true);Field("Maps","Extracted maps folder · needed for world-drop areas",original.MapFolder,true);Field("Client","WoW client root · needed for 3D models (.build.info)",original.ClientFolder,true);Field("MariaDB","MariaDB installation / tools folder · optional, local reference only",original.MariaDbFolder,true);
        downloads.IsChecked=original.AllowAssetDownloads;form.Children.Add(downloads);var note=DesignerWindow.Text("Supports the existing Classic 1.60.1 server/client data layout. A MariaDB installation folder is not required for a remote server. The app creates its backup database and missing editor history tables at startup; the MariaDB user needs permission to create them. The app connects through host and port; it does not start or manage the MariaDB service. Settings and password stay outside the project. Restart after saving to apply connection/folder changes safely.",12);note.TextWrapping=TextWrapping.Wrap;note.Margin=new Thickness(0,12,0,0);form.Children.Add(note);feedback.Text=AppSettings.LoadError??"";
    }
    private string SafeError(Exception ex)=>string.IsNullOrEmpty(password.Password)?ex.Message:ex.Message.Replace(password.Password,"[hidden]",StringComparison.Ordinal);
    private EditorSettings Read()=>original with{Server=fields["Server"].Text.Trim(),Port=uint.TryParse(fields["Port"].Text,out uint port)?port:0,User=fields["User"].Text.Trim(),Password=password.Password,SslMode=(string?)ssl.SelectedItem??"Preferred",ConnectionTimeout=uint.TryParse(fields["Timeout"].Text,out uint timeout)?timeout:0,HotfixDatabase=fields["Hotfix"].Text.Trim(),WorldDatabase=fields["World"].Text.Trim(),CharacterDatabase=fields["Characters"].Text.Trim(),BackupDatabase=fields["Backup"].Text.Trim(),Db2Folder=fields["Db2"].Text.Trim(),MapFolder=fields["Maps"].Text.Trim(),ClientFolder=fields["Client"].Text.Trim(),MariaDbFolder=fields["MariaDB"].Text.Trim(),AllowAssetDownloads=downloads.IsChecked==true};
}
